    replacementDelegationId: z.string().regex(AI_DELEGATION_ID_PATTERN).describe('같은 카드에서 나중에 작업과 결과 전달을 완료한 후속 위임 ID'),
    expectedUpdatedAt: z.string().min(1).describe('과거 위임 목록에서 확인한 최신 updatedAt'),
