  registerTool(server, 'mindnprogress_recover_ai_delegation', '원래 맡긴 범위에서 현재 상태와 미완료 부분을 확인하세요. 그룹 총괄 AI가 범위를 변경하려면 사용자 승인을 먼저 확인합니다. AionCore 재시작, 연결 끊김 또는 필수 체크포인트·통합 실패로 recovery-required 또는 integration-recovery-required가 된 AI 위임을 기존 대화와 기존 작업공간에서 명시적으로 재개합니다. parent-wake-failed는 list_ai_delegations가 recoveryAvailable=true를 반환하고 사용자가 사용량·요청 한도 또는 모델 용량 부족 해소를 확인한 경우에만 같은 방식으로 재개할 수 있습니다. waiting-usage-limit, waiting-rate-limit, waiting-model-capacity도 같은 조건으로 재개하며 worker가 없는 문서 조정 위임도 지원합니다. waiting-child-resume은 사용자가 중지 후 재개를 요청한 경우에만 처리합니다. 접수 여부가 불명확하면 새 실행을 만들지 말고 mindnprogress_refresh_ai_delegation으로 확인하세요. 원래 지시를 자동 재생하지 않으며, 현재 카드·Git·작업공간 상태를 확인한 뒤 미완료 부분만 수행하도록 새 복구 지시를 전달합니다. 복구 호출 후 mindnprogress_list_ai_delegations로 실제 상태를 확인하세요.', {
    mapId: z.string().min(1).describe('위임을 시작한 상위 문서 ID. 원래 상위 대화가 중단되었어도 같은 상위 카드에 연결된 새 대화에서 복구할 수 있습니다.'),
    delegationId: z.string().regex(AI_DELEGATION_ID_PATTERN).describe('mindnprogress_list_ai_delegations에서 확인한 복구 대상 위임 ID'),
    instruction: z.string().min(1).max(100000).describe('현재 상태를 확인한 뒤 이어서 수행할 범위와 완료 조건. 커밋 전 변경은 보존하고 완료된 작업은 반복하지 않습니다. 구버전 failed-clean 작업은 MindNProgress가 새 lease를 배정할 수 있으므로 이번 전문의 할당 경로·브랜치·세션을 확인하도록 지시하세요.'),
    sourceRevision: z.number().int().positive().describe('get_context 또는 get_document에서 확인한 현재 문서 version'),
  }, async ({ mapId, delegationId, instruction, sourceRevision }) => {
    const origin = delegationOriginForMap(mapId)
    return apiRequest(`/api/maps/${encodeURIComponent(mapId)}/ai-delegations/${encodeURIComponent(delegationId)}/recover`, {
      method: 'POST',
      aiMapId: origin.mapId,
      aiCardId: origin.cardId,
      aiAttributionToken: origin.attributionToken,
      aiEditorId: origin.editorId,
      aiType: origin.aiType,
      aiModel: origin.aiModel,
      timeoutMs: 60_000,
      body: JSON.stringify({ instruction, sourceRevision }),
    })
  })

  for (const [name, action, description] of [
    ['mindnprogress_refresh_ai_delegation', 'refresh', '기존 위임 operation의 실제 상태를 다시 확인하고 위임 메타데이터를 동기화합니다. AI 실행 요청·재위임·카드 변경은 하지 않습니다. 같은 대화의 다른 턴을 임의로 완료 근거로 삼지 않습니다. 담당 상위 AI가 list_ai_delegations(includeResult=true)로 원문을 읽은 뒤 acknowledgeResultHash에 반환된 resultHash를 명시하면 실행·통합이 끝난 해당 결과의 수신을 확인하고 사용자용 완료 전문을 상위 대화에 기록합니다. reportArchived/reportArchivePending은 전문 저장 여부이며 실패 시 AI 실행 없이 재시도합니다. 이 확인은 품질 검증 완료나 후속 작업의 사용자 승인이 아닙니다.'],
    ['mindnprogress_retry_ai_delegation_report', 'retry-report', '사용자 요청과 기존 승인 범위 안에서 완료됐지만 상위 보고만 실패한 위임 결과를 다시 전달합니다. 하위 작업은 재실행하지 않습니다. 캡처 원문이 없거나 해시·실행 턴 무결성이 맞지 않으면 최신 응답으로 대체하지 않고 원문 미포함 메타데이터만 전달합니다. 실행 후 list_ai_delegations에서 보고 상태와 resultHash를 확인하세요.'],
  ]) {
    registerTool(server, name, description, {
      mapId: z.string().min(1).describe('이 위임을 시작한 상위 문서 ID'),
      delegationId: z.string().regex(AI_DELEGATION_ID_PATTERN),
      expectedUpdatedAt: z.string().min(1).describe('위임 목록에서 확인한 최신 updatedAt'),
      ...(action === 'refresh' ? { acknowledgeResultHash: z.string().regex(/^[a-f0-9]{64}$/).optional().describe('담당 상위 AI가 실제 읽은 결과의 resultHash. 생략하면 상태만 다시 확인합니다.') } : {}),
    }, async ({ mapId, delegationId, expectedUpdatedAt, acknowledgeResultHash }) => {
      const origin = delegationOriginForMap(mapId)
      return apiRequest(`/api/maps/${encodeURIComponent(mapId)}/ai-delegations/${encodeURIComponent(delegationId)}/${action}`, {
        method: 'POST', aiMapId: origin.mapId, aiCardId: origin.cardId,
        aiAttributionToken: origin.attributionToken, aiEditorId: origin.editorId,
        aiType: origin.aiType, aiModel: origin.aiModel,
        body: JSON.stringify({ expectedUpdatedAt, ...(action === 'refresh' && acknowledgeResultHash ? { acknowledgeResultHash } : {}) }),
      })
    })
  }

  registerTool(server, 'mindnprogress_finalize_ai_coordination', '사용자가 명시한 경우에만 결과가 보존된 coordination-only 위임을 종료해 상위 AI에 전달합니다. 변경 없이 한도에 막힌 같은 카드의 과거 시도가 있고 완료된 후속 위임이 있으면 그 과거 시도만 superseded로 함께 정리될 수 있습니다. 카드·대기·실제 하위 상태는 바꾸지 않고 하위 AI도 재실행하지 않습니다. 일반 구현·결과 없는 실행에는 사용할 수 없으며 list_ai_delegations로 종료 대상과 동반 정리 결과를 확인하세요.', {
