  binding: Object.freeze({
    state: 'bound',
    snapshot: '현재 응답은 호출 시점의 스냅샷이며 이후 변경을 자동 반영하지 않습니다.',
  }),
  refresh: Object.freeze({
    repeatGetContext: false,
    card: 'mindnprogress_get_card',
