    const origin = delegationOriginForMap(mapId)
    return apiRequest(`/api/maps/${encodeURIComponent(mapId)}/ai-delegations/${encodeURIComponent(delegationId)}/supersede`, {
      method: 'POST', aiMapId: origin.mapId, aiCardId: origin.cardId,
      aiAttributionToken: origin.attributionToken, aiEditorId: origin.editorId,
      aiType: origin.aiType, aiModel: origin.aiModel,
      body: JSON.stringify({ expectedUpdatedAt, replacementDelegationId, confirmSupersededByCompletedDelegation: true }),
    })
